"use client"

import { useState, useCallback, useRef, useEffect } from "react"
import type { FileUploadConfig } from "@/types/file-upload.types"
import { validateFiles } from "@/lib/file-validation"
import {
  DEFAULT_MAX_FILE_SIZE_MB,
  DEFAULT_ACCEPTED_FORMATS,
} from "@/constants/file-upload.constants"

interface UseFileUploadProps {
  /** Modo controlado: quando definido, o estado vem do pai */
  files?: File[]
  onFileSelect?: (files: File[]) => void
  config?: Partial<FileUploadConfig>
}

function clearInputElement(input: HTMLInputElement | null) {
  if (input) {
    input.value = ""
  }
}

export function useFileUpload({
  files: controlledFiles,
  onFileSelect,
  config,
}: UseFileUploadProps = {}) {
  const [uncontrolledFiles, setUncontrolledFiles] = useState<File[]>([])
  const [error, setError] = useState<string | null>(null)
  const [isDragging, setIsDragging] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)
  const dragCounterRef = useRef(0)

  const isControlled = controlledFiles !== undefined
  const selectedFiles = isControlled ? controlledFiles : uncontrolledFiles

  const maxSize = config?.maxSize ?? DEFAULT_MAX_FILE_SIZE_MB
  const acceptedFormats = config?.acceptedFormats ?? DEFAULT_ACCEPTED_FORMATS
  const maxFiles = config?.maxFiles

  const onFileSelectRef = useRef(onFileSelect)
  useEffect(() => {
    onFileSelectRef.current = onFileSelect
  }, [onFileSelect])

  const updateFiles = useCallback(
    (next: File[]) => {
      if (!isControlled) {
        setUncontrolledFiles(next)
      }
      onFileSelectRef.current?.(next)
    },
    [isControlled],
  )

  // Sincroniza input quando o pai limpa arquivos (modo controlado)
  useEffect(() => {
    if (isControlled && controlledFiles.length === 0) {
      clearInputElement(inputRef.current)
    }
  }, [isControlled, controlledFiles])

  // Modo não controlado: notifica o pai após mudanças internas
  useEffect(() => {
    if (!isControlled) {
      onFileSelectRef.current?.(uncontrolledFiles)
    }
  }, [isControlled, uncontrolledFiles])

  const addFiles = useCallback(
    (incoming: FileList) => {
      const validationResult = validateFiles(
        incoming,
        acceptedFormats,
        maxSize,
        maxFiles,
        selectedFiles.length,
      )

      if (!validationResult.isValid) {
        setError(validationResult.errorMessage)
        clearInputElement(inputRef.current)
        return
      }

      setError(null)
      const newFiles = Array.from(incoming)
      updateFiles([...selectedFiles, ...newFiles])
      clearInputElement(inputRef.current)
    },
    [acceptedFormats, maxSize, maxFiles, selectedFiles, updateFiles],
  )

  const removeFile = useCallback(
    (index: number) => {
      const next = selectedFiles.filter((_, i) => i !== index)
      updateFiles(next)
      setError(null)
    },
    [selectedFiles, updateFiles],
  )

  const reset = useCallback(() => {
    updateFiles([])
    setError(null)
    clearInputElement(inputRef.current)
  }, [updateFiles])

  const handleInputChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const incoming = event.target.files
      if (incoming && incoming.length > 0) {
        addFiles(incoming)
      }
    },
    [addFiles],
  )

  const handleDragEnter = useCallback(
    (event: React.DragEvent<HTMLDivElement>) => {
      event.preventDefault()
      dragCounterRef.current += 1
      setIsDragging(true)
    },
    [],
  )

  const handleDrop = useCallback(
    (event: React.DragEvent<HTMLDivElement>) => {
      event.preventDefault()
      dragCounterRef.current = 0
      setIsDragging(false)
      const incoming = event.dataTransfer.files
      if (incoming && incoming.length > 0) {
        addFiles(incoming)
      }
    },
    [addFiles],
  )

  const handleDragOver = useCallback(
    (event: React.DragEvent<HTMLDivElement>) => {
      event.preventDefault()
    },
    [],
  )

  const handleDragLeave = useCallback(
    (event: React.DragEvent<HTMLDivElement>) => {
      event.preventDefault()
      dragCounterRef.current -= 1
      if (dragCounterRef.current <= 0) {
        dragCounterRef.current = 0
        setIsDragging(false)
      }
    },
    [],
  )

  const openFileSelector = useCallback(() => {
    inputRef.current?.click()
  }, [])

  return {
    selectedFiles,
    error,
    isDragging,
    inputRef,
    maxSize,
    acceptedFormats,
    maxFiles,
    removeFile,
    reset,
    handleInputChange,
    handleDragEnter,
    handleDrop,
    handleDragOver,
    handleDragLeave,
    openFileSelector,
  }
}

"use client"

import { useEffect, useMemo, useState } from "react"

function fileKey(file: File): string {
  return `${file.name}-${file.size}-${file.lastModified}`
}

/**
 * Gera URLs de preview para imagens e revoga ao desmontar ou remover
 */
export function useFilePreviews(files: File[]) {
  const [previewMap, setPreviewMap] = useState<Record<string, string>>({})

  const imageFiles = useMemo(
    () => files.filter((f) => f.type.startsWith("image/")),
    [files],
  )

  useEffect(() => {
    const next: Record<string, string> = {}
    for (const file of imageFiles) {
      next[fileKey(file)] = URL.createObjectURL(file)
    }

    setPreviewMap(next)

    return () => {
      Object.values(next).forEach((url) => URL.revokeObjectURL(url))
    }
  }, [imageFiles])

  const getPreviewUrl = (file: File) => previewMap[fileKey(file)]

  return { getPreviewUrl }
}

import type {
  FileValidationResult,
  SupportedFileFormat,
} from "@/types/file-upload.types"
import {
  BYTES_PER_MB,
  VALIDATION_ERRORS,
} from "@/constants/file-upload.constants"
import { getAllowedMimeTypes } from "@/lib/file-mime-types"

/**
 * Extrai a extensão de um arquivo
 * @param filename - Nome do arquivo
 * @returns Extensão em maiúsculas ou string vazia
 */
export function getFileExtension(filename: string): string {
  const parts = filename.split(".")
  if (parts.length < 2) return ""
  return parts.pop()?.toUpperCase() ?? ""
}

/**
 * Valida se um arquivo está dentro dos critérios estabelecidos
 * @param file - Arquivo a ser validado
 * @param acceptedFormats - Formatos aceitos
 * @param maxSizeMB - Tamanho máximo em MB
 * @returns Resultado da validação
 */
export function validateFile(
  file: File,
  acceptedFormats: SupportedFileFormat[],
  maxSizeMB: number,
): FileValidationResult {
  const extension = getFileExtension(file.name)
  const normalizedFormats = acceptedFormats.map((f) => f.toUpperCase())

  if (!extension) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.UNSUPPORTED_FORMAT(acceptedFormats),
    }
  }

  // Validação de extensão
  if (!normalizedFormats.includes(extension)) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.UNSUPPORTED_FORMAT(acceptedFormats),
    }
  }

  // Validação de MIME type (quando o navegador informa o tipo)
  const allowedMimes = getAllowedMimeTypes(acceptedFormats)
  if (file.type && !allowedMimes.includes(file.type)) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.INVALID_MIME(acceptedFormats),
    }
  }

  // Validação de tamanho
  const maxSizeBytes = maxSizeMB * BYTES_PER_MB
  if (file.size > maxSizeBytes) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.FILE_TOO_LARGE(maxSizeMB),
    }
  }

  return {
    isValid: true,
    errorMessage: null,
  }
}

/**
 * Valida múltiplos arquivos
 * @param files - Lista de arquivos
 * @param acceptedFormats - Formatos aceitos
 * @param maxSizeMB - Tamanho máximo em MB
 * @param maxFiles - Limite total de arquivos (incluindo os já selecionados)
 * @param currentCount - Quantidade de arquivos já na seleção
 * @returns Resultado da primeira validação que falhar, ou sucesso
 */
export function validateFiles(
  files: FileList,
  acceptedFormats: SupportedFileFormat[],
  maxSizeMB: number,
  maxFiles?: number,
  currentCount = 0,
): FileValidationResult {
  if (
    maxFiles !== undefined &&
    currentCount + files.length > maxFiles
  ) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.TOO_MANY_FILES(maxFiles),
    }
  }

  for (let i = 0; i < files.length; i++) {
    const result = validateFile(files[i], acceptedFormats, maxSizeMB)
    if (!result.isValid) {
      return result
    }
  }

  return {
    isValid: true,
    errorMessage: null,
  }
}

import { BYTES_PER_KB, BYTES_PER_MB } from "@/constants/file-upload.constants"
import { getAcceptAttribute } from "@/lib/file-mime-types"
import type { SupportedFileFormat } from "@/types/file-upload.types"

/**
 * Formata tamanho de arquivo em bytes para formato legível
 * @param bytes - Tamanho em bytes
 * @returns String formatada (ex: "1.5 MB", "256 KB")
 */
export function formatFileSize(bytes: number): string {
  if (bytes < BYTES_PER_KB) {
    return `${bytes} B`
  }

  if (bytes < BYTES_PER_MB) {
    return `${(bytes / BYTES_PER_KB).toFixed(1)} KB`
  }

  return `${(bytes / BYTES_PER_MB).toFixed(1)} MB`
}

/**
 * Gera mensagem pluralizada para quantidade de arquivos
 * @param count - Número de arquivos
 * @returns Mensagem formatada
 */
export function getFileCountMessage(count: number): string {
  if (count === 0) return "Arraste os arquivos aqui"
  if (count === 1) return "1 arquivo selecionado"
  return `${count} arquivos selecionados`
}

/**
 * Formata array de formatos aceitos para o atributo accept do input
 * @param formats - Array de formatos (ex: ["PNG", "JPG", "PDF"])
 * @returns String de MIME types separados por vírgula
 */
export function formatAcceptAttribute(formats: string[]): string {
  return getAcceptAttribute(formats as SupportedFileFormat[])
}

import type { SupportedFileFormat } from "@/types/file-upload.types"
import { FILE_FORMAT_MIME_MAP } from "@/constants/file-upload.constants"

/**
 * Converte formatos de arquivo para atributo accept do input
 * @param formats - Array de formatos suportados
 * @returns String para usar no atributo accept (ex: "image/png,image/jpeg")
 */
export function getAcceptAttribute(formats: SupportedFileFormat[]): string {
  return formats
    .map((format) => {
      const mimeType = FILE_FORMAT_MIME_MAP[format.toUpperCase()]
      return mimeType ?? `.${format.toLowerCase()}`
    })
    .join(",")
}

/**
 * Retorna MIME types permitidos para os formatos aceitos
 */
export function getAllowedMimeTypes(
  formats: SupportedFileFormat[],
): string[] {
  const mimes = formats.map(
    (format) => FILE_FORMAT_MIME_MAP[format.toUpperCase()],
  )
  return [...new Set(mimes.filter(Boolean))]
}

import type { SupportedFileFormat } from "@/types/file-upload.types"
import { FILE_FORMAT_MIME_MAP } from "@/constants/file-upload.constants"

/**
 * Detecta MIME type pelos magic bytes do ficheiro
 */
export function sniffMimeType(bytes: Uint8Array): string | null {
  if (bytes.length < 4) return null

  // PDF: %PDF
  if (
    bytes[0] === 0x25 &&
    bytes[1] === 0x50 &&
    bytes[2] === 0x44 &&
    bytes[3] === 0x46
  ) {
    return "application/pdf"
  }

  // PNG
  if (
    bytes[0] === 0x89 &&
    bytes[1] === 0x50 &&
    bytes[2] === 0x4e &&
    bytes[3] === 0x47
  ) {
    return "image/png"
  }

  // JPEG
  if (bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) {
    return "image/jpeg"
  }

  // MP4: ....ftyp
  if (bytes.length >= 12) {
    const ftyp = String.fromCharCode(
      bytes[4],
      bytes[5],
      bytes[6],
      bytes[7],
    )
    if (ftyp === "ftyp") {
      return "video/mp4"
    }
  }

  return null
}

/**
 * Valida se o MIME detetado corresponde aos formatos aceites
 */
export function isMimeAllowedForFormats(
  mime: string,
  formats: SupportedFileFormat[],
): boolean {
  const allowed = formats.map(
    (f) => FILE_FORMAT_MIME_MAP[f.toUpperCase()],
  )
  return allowed.includes(mime)
}

import * as React from "react"

export type SupportedFileFormat = "PNG" | "JPG" | "JPEG" | "PDF" | "MP4"

export interface FileValidationResult {
  isValid: boolean
  errorMessage: string | null
}

export interface FileUploadConfig {
  maxSize: number
  acceptedFormats: SupportedFileFormat[]
  maxFiles?: number
}

export interface FileUploadLabels {
  title?: string
  description?: string
  dropHint?: string
  browseHint?: string
  supportedFormats?: string
  maxSize?: string
  clear?: string
  upload?: string
  uploading?: string
}

export interface FileUploadHandle {
  reset: () => void
}

export interface FileUploadProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onDrop"> {
  /** Modo controlado: lista de arquivos gerenciada pelo pai */
  files?: File[]
  onFileSelect?: (files: File[]) => void
  onUpload?: (files: File[]) => void | Promise<void>
  onReset?: () => void
  maxSize?: number
  maxFiles?: number
  acceptedFormats?: SupportedFileFormat[]
  isLoading?: boolean
  /** Exibe o botão "Enviar" no rodapé do card (padrão: true) */
  showUploadButton?: boolean
  /** Miniatura para ficheiros de imagem (padrão: true) */
  showPreview?: boolean
  labels?: FileUploadLabels
}
